package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethodMap;
import com.fasterxml.jackson.databind.introspect.ClassIntrospector.MixInResolver;
import com.fasterxml.jackson.databind.util.Annotations;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.lang.annotation.Annotation;
import java.lang.reflect.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for _addMethodMixIns.
 * Since the method is protected, we use a Spy or a subclass to access it.
 */
public class AnnotatedClass__addMethodMixIns_TriageGen0Test {

    // Mock classes for testing reflection
    public static class TargetClass {
        public void existingMethod() {}
    }

    public static class MixInClass {
        public void mixInMethod() {}
        private void privateMethod() {} // Should be filtered by _isIncludableMemberMethod
    }

    public static class SubMixInClass extends MixInClass {
        public void subMixInMethod() {}
    }

    // A subclass to expose the protected method for testing
    private static class TestableAnnotatedClass extends AnnotatedClass {
        protected TestableAnnotatedClass(Class<?> cls, com.fasterxml.jackson.databind.cfg.AnnotationIntrospector aintr, 
                                       com.fasterxml.jackson.databind.cfg.MixInResolver mir) {
            super(cls, aintr, mir);
        }

        @Override
        public void _addMethodMixIns(Class<?> targetClass, AnnotatedMethodMap methods,
                                     Class<?> mixInCls, AnnotatedMethodMap mixIns) {
            super._addMethodMixIns(targetClass, methods, mixInCls, mixIns);
        }
    }

    @Test
    public void testAddMethodMixIns_WhenMethodAlreadyExistsInTarget() throws Exception {
        // Setup
        com.fasterxml.jackson.databind.cfg.AnnotationIntrospector aintr = mock(com.fasterxml.jackson.databind.cfg.AnnotationIntrospector.class);
        com.fasterxml.jackson.databind.cfg.MixInResolver mir = mock(com.fasterxml.jackson.databind.cfg.MixInResolver.class);

        TestableAnnotatedClass annotatedClass = new TestableAnnotatedClass(TargetClass.class, aintr, mir);
        AnnotatedMethodMap methods = mock(AnnotatedMethodMap.class);
        AnnotatedMethodMap mixIns = mock(AnnotatedMethodMap.class);

        // Mocking the method in TargetClass that the MixIn will try to augment
        Method targetMethod = TargetClass.class.getMethod("existingMethod");
        AnnotatedMethod am = mock(AnnotatedMethod.class);
        when(methods.find(any(Method.class))).thenAnswer(invocation -> {
            Method m = invocation.getArgument(0);
            if (m.getName().equals("existingMethod")) return am;
            return null;
        });

        // We need to make sure the MixInClass has a method with the same signature to trigger 'am != null'
        // However, the code uses mixin.getDeclaredMethods(). 
        // Let's use a more controlled approach via Mockito spy on the annotatedClass to control internal calls
        TestableAnnotatedClass spyClass = spy(annotatedClass);

        // We simulate the mixin class having a method that matches the target method name
        // Note: The logic in the provided code relies on mixin.getDeclaredMethods()
        // For the 'am != null' branch, the method 'm' from MixInClass must be found in 'methods'

        // Prepare a MixIn class that has a method that exists in the target
        class MatchMixIn {
            public void existingMethod() {}
        }

        spyClass._addMethodMixIns(TargetClass.class, methods, MatchMixIn.class, mixIns);

        // Verify _addMixUnders was called because am != null
        verify(spyClass)._addMixUnders(any(Method.class), eq(am));
    }

    @Test
    public void testAddMethodMixIns_WhenMethodIsNewInMixIn() throws Exception {
        // Setup
        com.fasterxml.jackson.databind.cfg.AnnotationIntrospector aintr = mock(com.fasterxml.jackson.databind.cfg.AnnotationIntrospector.class);
        com.fasterxml.jackson.databind.cfg.MixInResolver mir = mock(com.fasterxml.jackson.databind.cfg.MixInResolver.class);

        TestableAnnotatedClass annotatedClass = new TestableAnnotatedClass(TargetClass.class, aintr, mir);
        AnnotatedMethodMap methods = mock(AnnotatedMethodMap.class);
        AnnotatedMethodMap mixIns = mock(AnnotatedMethodMap.class);

        // Mocking: method is NOT in target methods
        when(methods.find(any(Method.class))).thenReturn(null);

        TestableAnnotatedClass spyClass = spy(annotatedClass);

        // Use MixInClass which has 'mixInMethod'
        spyClass._addMethodMixIns(TargetClass.class, methods, MixInClass.class, mixIns);

        // Verify _constructMethod was called and result was added to mixIns
        verify(spyClass, atLeastOnce())._constructMethod(any(Method.class));
        // Since we can't easily check the exact content of mixIns without its implementation, 
        // we rely on the fact that _constructMethod was called for the includable method.
    }

    @Test
    public void testAddMethodMixIns_SkipsIncludableFalse() throws Exception {
        com.fasterxml.jackson.databind.cfg.AnnotationIntrospector aintr = mock(com.fasterxml.jackson.databind.cfg.AnnotationIntrospector.class);
        com.fasterxml.jackson.databind.cfg.MixInResolver mir = mock(com.fasterxml.jackson.databind.cfg.MixInResolver.class);

        TestableAnnotatedClass annotatedClass = new TestableAnnotatedClass(TargetClass.class, aintr, mir);
        AnnotatedMethodMap methods = mock(AnnotatedMethodMap.class);
        AnnotatedMethodMap mixIns = mock(AnnotatedMethodMap.class);

        TestableAnnotatedClass spyClass = spy(annotatedClass);

        // MixInClass has a private method. _isIncludableMemberMethod should return false.
        // We need to ensure the spy returns false for the private method.
        // We don't strictly need to mock _isIncludableMemberMethod if we know how it behaves, 
        // but to be safe for branch coverage:

        spyClass._addMethodMixIns(TargetClass.class, methods, MixInClass.class, mixIns);

        // Verify that for the private method, no construction happened.
        // MixInClass has 1 public method and 1 private.
        // If _isIncludableMemberMethod works, only 1 call to _constructMethod should happen.
        verify(spyClass, times(1))._constructMethod(any(Method.class));
    }

    @Test
    public void testAddMethodMixIns_MultiLevelMerge() throws Exception {
        com.fasterxml.jackson.databind.cfg.AnnotationIntrospector aintr = mock(com.fasterxml.jackson.databind.cfg.AnnotationIntrospector.class);
        com.fasterxml.jackson.databind.cfg.MixInResolver mir = mock(com.fasterxml.jackson.databind.cfg.MixInResolver.class);

        TestableAnnotatedClass annotatedClass = new TestableAnnotatedClass(TargetClass.class, aintr, mir);
        AnnotatedMethodMap methods = mock(AnnotatedMethodMap.class);
        AnnotatedMethodMap mixIns = mock(AnnotatedMethodMap.class);

        TestableAnnotatedClass spyClass = spy(annotatedClass);
        when(methods.find(any(Method.class))).thenReturn(null);

        // Use SubMixInClass which inherits from MixInClass
        spyClass._addMethodMixIns(TargetClass.class, methods, SubMixInClass.class, mixIns);

        // Should find methods from both SubMixInClass and MixInClass (parents)
        // SubMixInClass: subMixInMethod
        // MixInClass: mixInMethod
        verify(spyClass, times(2))._constructMethod(any(Method.class));
    }
}
